export type TransferStatus = z.infer<typeof TransferStatusSchema>;

export const TriggerExecutionStatusValues = ["pending","processing","completed","failed"] as const;
export const TriggerExecutionStatus = { PENDING: "pending", PROCESSING: "processing", COMPLETED: "completed", FAILED: "failed" } as const;
export const TriggerExecutionStatusSchema = z.intersection(z.union([z.literal("pending"), z.literal("processing"), z.literal("completed"), z.literal("failed")]), z.string());
export type TriggerExecutionStatus = z.infer<typeof TriggerExecutionStatusSchema>;

export const TriggerExecutionHistoryItemSchema = z.looseObject({ ["agent_id"]: z.guid(), ["created_at"]: z.iso.datetime({ offset: true, local: true }), ["finished_at"]: z.union([z.iso.datetime({ offset: true, local: true }), z.null()]), ["id"]: z.guid(), ["scheduled_at"]: z.iso.datetime({ offset: true, local: true }), ["source"]: z.string(), ["started_at"]: z.union([z.iso.datetime({ offset: true, local: true }), z.null()]), ["status"]: TriggerExecutionStatusSchema, ["trigger_id"]: z.guid() });
export type TriggerExecutionHistoryItem = z.infer<typeof TriggerExecutionHistoryItemSchema>;

export const TriggerExecutionHistoryPageSchema = z.looseObject({ ["items"]: z.array(TriggerExecutionHistoryItemSchema), ["next_cursor"]: z.union([z.string(), z.null()]) });
export type TriggerExecutionHistoryPage = z.infer<typeof TriggerExecutionHistoryPageSchema>;

export const TriggerResponseSchema = z.looseObject({ ["config"]: JsonOutputObjectSchema, ["cooldown_seconds"]: z.number().refine(Number.isInteger), ["created_at"]: z.union([z.string(), z.null()]).optional(), ["expires_at"]: z.union([z.string(), z.null()]).optional(), ["fire_count"]: z.number().refine(Number.isInteger), ["focus_ref"]: z.union([z.string(), z.null()]).optional(), ["id"]: z.string(), ["is_enabled"]: z.boolean(), ["is_system"]: z.boolean().optional(), ["last_fired_at"]: z.union([z.string(), z.null()]).optional(), ["max_fires"]: z.union([z.number().refine(Number.isInteger), z.null()]).optional(), ["name"]: z.string(), ["reason"]: z.string(), ["type"]: z.string() });
