export const TriggerUpdateSchema = z.looseObject({ ["config"]: z.union([JsonInputObjectSchema, z.null()]).optional(), ["cooldown_seconds"]: z.union([z.number().refine(Number.isInteger), z.null()]).optional(), ["expires_at"]: z.union([z.string(), z.null()]).optional(), ["is_enabled"]: z.union([z.boolean(), z.null()]).optional(), ["max_fires"]: z.union([z.number().refine(Number.isInteger), z.null()]).optional(), ["reason"]: z.union([z.string(), z.null()]).optional() });
